const bill=document.getElementById('bill'),people=document.getElementById('people'),tip=document.getElementById('tip'),roundUp=document.getElementById('roundUp');
const err=document.getElementById('err');
const eachLabel=document.getElementById('eachLabel');
bill.value='87.50';people.value='4';tip.value='15';
const fmt=n=>n.toFixed(2);
function update(){
 const b=parseFloat(bill.value),p=parseInt(people.value,10),t=parseFloat(tip.value);
 const rTip=document.getElementById('rTip'),rTotal=document.getElementById('rTotal'),rEach=document.getElementById('rEach');
 let msg='';
 if(!(b>=0)) msg='Enter the bill amount as a number, 0 or more.';
 else if(!(p>=1)) msg='Enter at least 1 person.';
 else if(!(t>=0)) msg='Enter the tip as a number, 0 or more.';
 err.textContent=msg;
 eachLabel.textContent=roundUp.checked?'Each person pays (rounded up)':'Each person pays';
 if(msg){rTip.textContent=rTotal.textContent=rEach.textContent='–';return;}
 const tipAmt=b*t/100,total=b+tipAmt;
 let each=total/p;
 if(roundUp.checked) each=Math.ceil(Math.round(each*100)/100);
 rTip.textContent=fmt(tipAmt);rTotal.textContent=fmt(total);rEach.textContent=fmt(each);
}
for(const el of [bill,people,tip]) el.addEventListener('input',update);
roundUp.addEventListener('change',update);
update();
